IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES
               WHERE TABLE_SCHEMA = 'RDT' AND TABLE_NAME = 'rdtFunctionCategory')
BEGIN
    CREATE TABLE [RDT].[rdtFunctionCategory]
    (
        [FunctionID]   [int]            NOT NULL,
        [StorerKey]    [nvarchar] (15)  NOT NULL CONSTRAINT [DF_rdtFunctionCategory_StorerKey]   DEFAULT (''),
        [Facility]     [nvarchar] (5)   NOT NULL CONSTRAINT [DF_rdtFunctionCategory_Facility]    DEFAULT (''),
        [Type]         [nvarchar] (50)  NOT NULL CONSTRAINT [DF_rdtFunctionCategory_Type]        DEFAULT ('Standard'),
        [Category]     [nvarchar] (100) NOT NULL CONSTRAINT [DF_rdtFunctionCategory_Category]    DEFAULT (''),
        [SubCategory]  [nvarchar] (100) NOT NULL CONSTRAINT [DF_rdtFunctionCategory_SubCategory] DEFAULT (''),
        [UDFCategory]  [nvarchar] (100) NOT NULL CONSTRAINT [DF_rdtFunctionCategory_UDFCategory] DEFAULT (''),
        [Active]       [nvarchar] (1)   NOT NULL CONSTRAINT [DF_rdtFunctionCategory_Active]      DEFAULT ('Y'),
        [AddDate]      [datetime]       NOT NULL CONSTRAINT [DF_rdtFunctionCategory_AddDate]     DEFAULT (getdate()),
        [AddWho]       [nvarchar] (128) NOT NULL CONSTRAINT [DF_rdtFunctionCategory_AddWho]      DEFAULT (suser_sname()),
        [EditDate]     [datetime]       NOT NULL CONSTRAINT [DF_rdtFunctionCategory_EditDate]    DEFAULT (getdate()),
        [EditWho]      [nvarchar] (128) NOT NULL CONSTRAINT [DF_rdtFunctionCategory_EditWho]     DEFAULT (suser_sname())
    ) ON [PRIMARY]

    ALTER TABLE [RDT].[rdtFunctionCategory] ADD CONSTRAINT [PKrdtFunctionCategory]
        PRIMARY KEY CLUSTERED ([FunctionID], [StorerKey], [Facility], [Category])
        ON [PRIMARY]

    ALTER TABLE [RDT].[rdtFunctionCategory] WITH NOCHECK ADD CONSTRAINT [CK_rdtFunctionCategory_Active]
        CHECK (([Active] IN ('Y', 'N')))

    CREATE NONCLUSTERED INDEX [IDX_rdtFunctionCategory_StorerFacility]
        ON [RDT].[rdtFunctionCategory] ([StorerKey], [Facility], [Category])
        ON [PRIMARY]

    GRANT DELETE ON [RDT].[rdtFunctionCategory] TO [NSQL]
    GRANT INSERT ON [RDT].[rdtFunctionCategory] TO [NSQL]
    GRANT SELECT ON [RDT].[rdtFunctionCategory] TO [NSQL]
    GRANT UPDATE ON [RDT].[rdtFunctionCategory] TO [NSQL]

    EXEC sp_addextendedproperty N'MS_Description', 'RDT function identifier', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'FunctionID'
    EXEC sp_addextendedproperty N'MS_Description', 'Storer/owner of the goods', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'StorerKey'
    EXEC sp_addextendedproperty N'MS_Description', 'Warehouse facility code', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'Facility'
    EXEC sp_addextendedproperty N'MS_Description', 'Function type classification (Standard, Retired or Customized)', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'Type'
    EXEC sp_addextendedproperty N'MS_Description', 'Function category', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'Category'
    EXEC sp_addextendedproperty N'MS_Description', 'Function sub-category', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'SubCategory'
    EXEC sp_addextendedproperty N'MS_Description', 'User-defined function category', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'UDFCategory'
    EXEC sp_addextendedproperty N'MS_Description', 'Indicates if this function category is active and available for use (Y/N)', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'Active'
    EXEC sp_addextendedproperty N'MS_Description', 'Date when the record was created. (System date)', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'AddDate'
    EXEC sp_addextendedproperty N'MS_Description', 'User who created the record', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'AddWho'
    EXEC sp_addextendedproperty N'MS_Description', 'Date when the record was last modified. (System date)', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'EditDate'
    EXEC sp_addextendedproperty N'MS_Description', 'User who last modified the record', 'SCHEMA', N'RDT', 'TABLE', N'rdtFunctionCategory', 'COLUMN', N'EditWho'
END
GO

IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES
           WHERE TABLE_SCHEMA = 'RDT' AND TABLE_NAME = 'rdtFunctionCategory')
BEGIN
    BEGIN TRY
        DELETE FROM [RDT].[rdtFunctionCategory]
        WHERE [StorerKey] = '' AND [Facility] = ''
    END TRY
    BEGIN CATCH
        PRINT 'Error occurred while deleting records from [RDT].[rdtFunctionCategory]: ' + ERROR_MESSAGE()
    END CATCH

    BEGIN TRY
    END TRY
    BEGIn CATCH
        PRINT 'Error inserting into RDTFunctionCategory: ' + ERROR_MESSAGE()
    END CATCH
END
GO
